<?php
page_header($carrier['name'].' top-ups and plans');
$plans=all('SELECT * FROM plans WHERE carrier_id=? AND active=1 ORDER BY sort_order,price_cents',[$carrier['id']]);
$labels=['monthly'=>'Monthly plans','refill'=>'Refill credit','addon'=>'Add-ons','offer'=>'Special offers'];$counts=[];
foreach($plans as $p){$category=catalog_product($carrier['slug'],$p['name'])['category'];$counts[$category]=($counts[$category]??0)+1;}
?>
<section class="container page-intro"><a class="back-link" href="/carriers">← All carriers</a><div class="carrier-title"><?=carrier_logo($carrier)?></div><h1><?=e($carrier['name'])?> top-ups & plans.</h1><p class="lead"><?=e($carrier['description'])?></p><p class="muted">Compare monthly packages, refill credit and extras. Check the eligibility shown on each option.</p></section>
<section class="container section compact"><div class="flow-steps"><span class="complete">1 · Your carrier</span><span class="current">2 · Choose your top-up</span><span>3 · Checkout</span></div>
<?php if(!$plans):?><div class="empty-state"><h2>Let’s find your top-up.</h2><p>Contact our team to confirm the right option for your number.</p><a class="button primary" href="/contact">Contact our team <?=icon('arrow')?></a></div><?php else:?>
<div class="catalog-filters" role="group" aria-label="Top-up type"><button type="button" data-catalog-filter="all" aria-pressed="true">All options <span><?=count($plans)?></span></button><?php foreach($labels as $key=>$label):if(empty($counts[$key]))continue;?><button type="button" data-catalog-filter="<?=e($key)?>" aria-pressed="false"><?=e($label)?> <span><?=$counts[$key]?></span></button><?php endforeach;?></div>
<p class="catalog-count muted" role="status" aria-live="polite"><?=count($plans)?> options available</p>
<div class="plans-grid"><?php foreach($plans as $p):$meta=catalog_product($carrier['slug'],$p['name']);$available=$meta['selectable']&&(request_checkout_enabled()||(!$p['verify_pricing']&&checkout_ready()));$period=$meta['period_label']?:((int)$p['validity_days']>0?$p['validity_days'].' days':'per month');$source=filter_var($meta['source_url'],FILTER_VALIDATE_URL)?$meta['source_url']:$carrier['source_url'];?><article class="plan-card <?=$p['popular']?'popular':''?>" data-catalog-category="<?=e($meta['category'])?>"><?php if($p['popular']):?><span class="popular-label">Featured plan</span><?php endif;?><p class="eyebrow product-kind"><?=e($labels[$meta['category']]??'Top-up')?></p><h2><?=e($p['name'])?></h2><div class="plan-price"><?=money($p['price_cents'])?><span>USD · <?=e($period)?></span></div><ul><li><?=icon('globe')?><?=e($p['data_allowance'])?></li><li><?=icon('phone')?><?=e($p['talk'])?></li><li><?=icon('mail')?><?=e($p['texts'])?></li></ul><p><?=e($p['description'])?></p><?php if($meta['eligibility']):?><p class="plan-eligibility"><strong>Eligibility</strong><?=e($meta['eligibility'])?></p><?php endif;?>
<?php if(!$meta['selectable']):?><a class="button secondary full" href="<?=e($source)?>" target="_blank" rel="noopener noreferrer">View carrier offer ↗</a><?php else:?><a class="button <?=$available?'primary':'secondary'?> full" href="<?=$available?'/checkout?plan='.$p['id']:'/contact'?>"><?=$available?'Select top-up':'Contact us'?> <?=icon('arrow')?></a><?php endif;?></article><?php endforeach;?></div><?php endif;?>
<div class="notice subtle"><?=icon('shield')?><span>Refill credit adds balance; it does not include a new monthly package. Add-ons require an eligible active plan. Carrier promotions may have new-line, AutoPay or upfront-payment conditions.</span></div>
<?php if(filter_var($carrier['source_url'],FILTER_VALIDATE_URL)):?><p class="section-note"><a href="<?=e($carrier['source_url'])?>" target="_blank" rel="noopener noreferrer">View <?=e($carrier['name'])?> details ↗</a></p><?php endif;?></section><script defer src="<?=asset('catalog.js')?>"></script><?php page_footer(); ?>
